// This file is generated by AI.

// git 状态的**值比较**。
//
// `git/status.ts` 在项目里**任何**文件变化后 400ms 就重跑一次 `git status` (编辑器自己的
// 自动保存在 800ms 后落盘, 所以编辑时必然被触发), 而 `setGitStatus` 拿到的是一个**新对象**:
// store 若无条件下发, 下游每个观察者 (编辑器的 git 色块 effect、仓库页列表、状态栏) 都会被
// 唤醒一次, 一次自动保存 = 一次全量重画。
//
// 因此把"没变就不通知"放在写入 store 的那一处。判据是纯函数, 可单独测试。

import type { GitFileStatus, GitIdentity, GitStatus } from '../commands/git';

function sameIdentity(a: GitIdentity | null, b: GitIdentity | null): boolean {
  if (a === b) return true;
  if (!a || !b) return false;
  return a.name === b.name && a.email === b.email;
}

function sameFile(a: GitFileStatus, b: GitFileStatus): boolean {
  return a.path === b.path && a.status === b.status && a.additions === b.additions && a.deletions === b.deletions;
}

function sameFiles(a: readonly GitFileStatus[], b: readonly GitFileStatus[]): boolean {
  if (a === b) return true;
  if (a.length !== b.length) return false;
  for (let index = 0; index < a.length; index += 1) {
    if (!sameFile(a[index], b[index])) return false;
  }
  return true;
}

/**
 * 两次 git 状态是否**内容相同** (含都是 `null`)。逐项比较界面会画出的字段: 是否已初始化、
 * 分支、提交身份、暂存/未暂存列表 (路径 / 状态字母 / 增删行数); 顺序也参与比较 —— 后端与
 * 前端都按路径排序, 顺序变了界面上就是一行移动, 那属于"变了"。
 */
export function sameGitStatus(a: GitStatus | null | undefined, b: GitStatus | null | undefined): boolean {
  if (a === b) return true;
  // `null` 与 `undefined` 都表示"没有状态", 两者之间不该算变化
  const aEmpty = a === null || a === undefined;
  const bEmpty = b === null || b === undefined;
  if (aEmpty || bEmpty) return aEmpty && bEmpty;
  if (a.initialized !== b.initialized || a.branch !== b.branch) return false;
  if (!sameIdentity(a.identity, b.identity)) return false;
  return sameFiles(a.staged, b.staged) && sameFiles(a.unstaged, b.unstaged);
}
